USE order_trade;
CREATE TABLE IF NOT EXISTS trade_order(order_id BIGINT PRIMARY KEY,order_no VARCHAR(64) NOT NULL,user_id BIGINT NOT NULL,status TINYINT NOT NULL,pay_status TINYINT NOT NULL,total_amount_cent BIGINT NOT NULL,pay_amount_cent BIGINT NOT NULL,item_count INT NOT NULL,pay_order_no VARCHAR(64),pay_time DATETIME(3),cancel_time DATETIME(3),finish_time DATETIME(3),cancel_reason VARCHAR(255),version INT NOT NULL DEFAULT 0,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY uk_order_no(order_no),KEY idx_user_create(user_id,create_time),KEY idx_user_status_create(user_id,status,create_time)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_order_item(id BIGINT PRIMARY KEY,order_id BIGINT NOT NULL,order_no VARCHAR(64) NOT NULL,user_id BIGINT NOT NULL,spu_id BIGINT NOT NULL,sku_id BIGINT NOT NULL,spu_name VARCHAR(128) NOT NULL,sku_name VARCHAR(128) NOT NULL,price_cent BIGINT NOT NULL,quantity INT NOT NULL,total_amount_cent BIGINT NOT NULL,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),KEY idx_order_id(order_id),KEY idx_order_no(order_no)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_order_status_log(id BIGINT PRIMARY KEY,order_id BIGINT NOT NULL,order_no VARCHAR(64) NOT NULL,user_id BIGINT NOT NULL,before_status TINYINT,after_status TINYINT NOT NULL,operate_type VARCHAR(32) NOT NULL,operator_id BIGINT,remark VARCHAR(255),create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY idx_order_time(order_id,create_time)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_route(order_no VARCHAR(64) PRIMARY KEY,order_id BIGINT NOT NULL,user_id BIGINT NOT NULL,db_shard INT NOT NULL,table_shard INT NOT NULL,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY uk_order_id(order_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reconciliation_exception(id BIGINT PRIMARY KEY,user_id BIGINT NOT NULL DEFAULT 0,biz_type VARCHAR(32) NOT NULL,biz_no VARCHAR(64) NOT NULL,exception_type VARCHAR(64) NOT NULL,detail TEXT,status TINYINT NOT NULL DEFAULT 0,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),KEY idx_user_status_time(user_id,status,create_time),KEY idx_status_time(status,create_time)) ENGINE=InnoDB;
